c(1, "header lines 1-7", "positioning", "Habit-Bull / HabitBull (App Store ID 1041482672; subtitle 'Daily Goal Planner · Best To Do List · Streak Tracker') by AppForge Inc. (bundle oristats.HabitBull; also an Android version) — 2,024 written reviews, 82 storefronts, 9 Nov 2015 → 6 Aug 2026 (130 months), extracted 8 Sep 2026; written mean 4.05 (1,291×5★, 227×4★, 122×3★, 81×2★, 303×1★); snapshot 20,955 public ratings at 4.65, ranked in 52 storefronts, best search rank 6, median 21.5, audience 'moderate'; praised for a decade as a simple, flexible tracker (yes/no or numeric habits, 'N times a week', streak calendars, a generous five-habit free tier) whose complaints come from what happened around the core — crash waves, a paid sync that doesn't work, a 2018 one-time → subscription switch, a July 2020 every-launch upsell whose close button started a purchase, and silent support", "free 5 habits; one-time premium $3.99–$4.99 until Jun 2018, then ~$19.99/yr subscription", "mixed", "2,024 reviews; 20,955 ratings at 4.65", "none", "corpus-level fact", "app-specific", [])
c(2, "§How to read this; §1.1–1.5", "data-caveat", "Method: all 2,024 reviews read individually in original language (English, Portuguese, Spanish, Catalan, German, French, Dutch, Danish, Swedish, Polish, Czech, Italian, Turkish, Vietnamese, Russian, Ukrainian, Chinese, Japanese, Korean, Arabic, Malayalam) in chronological order, 17 chunks of up to 125; hand-assigned from a 103-code, 12-family inductive taxonomy with a running codebook, earlier chunks revisited when later codes applied (USER_COACH, PAY_REGRET, MOT_WANT); 4,216 assignments (2.08 per review, median 2); validated 0 unknown IDs, 0 unassigned, 0 duplicate keys, 0 intra-review duplicates, 0 undefined codes, 0 of 103 unused; text cross-check after classification found two real misses, fixed; reconciliation exact against 82 by_country files, manifest (5:1,291 · 4:227 · 3:122 · 2:81 · 1:303; mean 4.0484) and _state.json (134 polled, 82 with reviews, all complete); one repeated title+body ('Good :: Good', MX 2017 and VN 2020) kept; denominator 2,024; signal bands <0.1% ignore · 0.1–0.5% weak · 0.5–1% emerging · 1–3% meaningful · 3–5% very strong · >5% high-priority; composite unions count each review once; text sub-cuts only inside hand-coded themes; no automated classifier; 13 fields, author/app_id/app_name/country_name unused; is_edited true for 4; vote_count>0 on 121 (5.98%), max 6, never weights; body median 111, mean 164.0", "n/a", "n/a", "2,024 (100%)", "none", "method statement", "app-specific", ["1615596534","5989825005","2070350968","11359320730","5501033289"])
c(3, "§Eight warnings 1; §1.6 #3", "data-caveat", "Written corpus more negative than the public rating and unevenly: written = 9.66% of public ratings (2,024 of 20,955), mean 4.05 sits 0.60★ below 4.65; gap 0.14★ in Australia but 1.07★ in the UK and 1.18★ in Brazil — written reviews over-represent moments when something broke; incidents produce bursts of 1★ writers who would otherwise never review", "n/a", "n/a", "9.66%; −0.60★; au −0.14, gb −1.07, br −1.18", "none", "corpus-level fact", "generalisable", [])
c(4, "§Eight warnings 2–5; §1.6 #1, #2, #4–#7", "data-caveat", "Caveats: volume collapsed after 2020 (399 in 2016, 288 in 2020, 60 in 2021, 16 in 2026; eras 709 / 400 / 597 / 189 / 129, one review = 0.78 points of E5); English-dominant (US 43.53%, six English-primary storefronts 1,310 = 64.72%, 67 non-Latin-script reviews = 3.31%; six storefronts clear 50); no version field (two reviewers quote 1.4.7 and 1.4.11); 14.48% carry no product experience (LOWINFO 261 + PREUSE 32 = 293, mean 4.89); prices reviewer-reported (two say '$20 a month' where everyone else says a year); no live store data and one external source (habit_apps_ranked.json); no developer responses in the data though reviewers mention canned replies; storefront ≠ language; 'paid' means the reviewer says they paid — one-time buyers, subscribers and trial converts, no conversion rate", "n/a", "n/a", "as listed", "none", "method statement", "app-specific", ["6706410264","7097957463","3278313008","5544529848","6360079136","7059744677","14394403203"])
c(5, "§Eight warnings 6; §1.7", "tactic", "Launch and press bursts: 38 reviews in launch week and 21 on 10 Nov 2015 (day two) citing a Reddit launch post and a developer who spoke with them there — organic but motivated early adopters (137 reviews in 2015 at 4.71); January 2016 holds 105 reviews (4.77) citing BuzzFeed and a TV review; Oct 2019 and Oct 2020 three Korean reviews say a rapper recommended the app; a 2016 reviewer received the full version free (developer promotion)", "Reddit launch post with developer present; press coverage", "5★-burst", "21 on 10 Nov 2015; 105 in Jan 2016 at 4.77; 137 in 2015 at 4.71", "do", "burst", "generalisable", ["1284433048","1308758985","1317049655","1317786863","1322958708","1327696946","4905479317","4912823642","6520274563","1322768678"])
c(6, "§1.7 rating prompt", "anti-pattern", "The in-app rating prompt: META_PROMPT 9 (0.44%, weak, mean 2.44) — 'You have asked me 4 time within 1 minute to rate your app'; a lock screen and rating dialog that trapped a user; 'Stop asking for a review'; one Brazilian found it cute; the prompt plausibly inflates short 5★ (LOWINFO reviews average 4.89) — a hypothesis, not a measured effect", "repeated rating prompts, one trapping a user behind the passcode lock", "complaint", "9 (0.44%, 2.44)", "dont", "weak", "generalisable", ["1956880711","1675008191","7738946654","1378213453"])
c(7, "§Eight warnings 6–7; §1.7", "data-caveat", "Integrity: 12 Jul 2020 holds 11 reviews, all during the pop-up backlash; one unverified 2024 allegation that positive reviews are bought; one advert for a coaching service and one joke review kept and coded; 24 reviews (1.19%, meaningful) contradict their rating, 19 of them 5★ describing a failure", "n/a", "n/a", "11 on 12 Jul 2020; 24 contradictions", "none", "method statement", "app-specific", ["11359320730","1528497631","1758524697"])

# PART 0
c(8, "Part 0 summary; §0.1 table (verbatim)", "insight", "The people who paid are the people who were let down: PAY_BOUGHT 165 (8.15%, high-priority, mean 2.56), 96 of them (58.2%) at 1–2★ — the unhappiest group; paid mean fell every era 4.24 (E1, 38 payers) → 2.78 (E2, 37) → 1.91 (E3, 56) → 1.41 (E4, 27); within payers (segment rates of 165): data & account continuity failure 69 (41.8%, 48.3% of that theme from payers); crashes 44 (26.7%); support does not reply 42 (25.5%, 50.6% of theme); sync between devices fails 36 (21.8%, 58.1%); asks for refund 17 (10.3%, 89.5%); purchase lost on reinstall / new phone 15 (9.1%, 83.3%)", "n/a", "1★-burst", table("## 0.1 The people who paid", 0), "must-never-break", "high-priority", "generalisable", [])
c(9, "§0.1 sync quotes; §2.4", "anti-pattern", "The headline paid feature was cross-device sync and reviewers say it did not work: 'I bought the premium because I wanted to sync. Can't sync anywhere and app says no signal' (us, 3★, 2019); 'Paid £17.49 to sync phone/iPad/watch and it doesn't work. No response from app developer and Apple won't help' (gb, 1★, 2020); 'if you subscribe you wont be able to sync across your devices!!! … if you change phone or reset your device YOU WILL NOT GET BACK YOUR DATA' (us, 1★, 2019); SYNC_BUG 62 (3.06%)", "paid sync broken", "1★-burst", "SYNC_BUG 62 (3.06%); 36 payers (21.8%)", "must-never-break", "high-priority", "generalisable", ["4823714493","5384533156","4956440235"])
c(10, "§0.2 table (verbatim)", "timeline", "Subscription-model backlash [U:sub_backlash] 82 (4.05%, very strong, mean 1.91) by era (verbatim): E1 Nov 2015–Jun 2017 709 reviews — friction 7 (1.0%), backlash 0, reliability 46 (6.5%), mean 4.67; E2 Jul 2017–May 2018 400 — 28 (7.0%), 0, 105 (26.2%), 3.99; E3 Jun 2018–Jun 2020 597 — 57 (9.5%), 18 (3.0%), 179 (30.0%), 3.84; E4 Jul 2020–Jun 2021 189 — 67 (35.4%), 55 (29.1%), 79 (41.8%), 2.72; E5 Jul 2021–Aug 2026 129 — 12 (9.3%), 9 (7.0%), 25 (19.4%), 3.72", "n/a", "1★-burst", table("## 0.2 The subscription switch", 0), "none", "table", "app-specific", [])
c(11, "§0.2 June 2018", "timeline", "June 2018 — one-time fee became an annual subscription: 'It was 4.99$ to unlock the premium features, now it's 19$ a year! From a license model to a subscription model, and about 400% increase in price, and all you get while updating? Changes' (us, 1★, 4 Jun 2018); PAY_PRICE_HIGH 42 (2.08%, meaningful, mean 2.71), 40 of 42 from June 2018 on", "one-time $4.99 → $19.99/yr", "1★-burst", "PAY_PRICE_HIGH 42 (2.71), 40 from Jun 2018", "product-rule", "meaningful", "generalisable", ["2640020936","2644893532"])
c(12, "§0.2 earlier buyers", "product-rule", "Earlier buyers asked to pay again: PAY_REGRESS 9 (0.44%, weak, mean 1.33), Dec 2019 → Jan 2025 — 'I bought HabitBull for a fixed price before they moved to a subscription model. I tried contacting them several times to ask them to honor my membership. Absolutely no reply, not one' (us, 1★, May 2020)", "one-time buyers not grandfathered", "1★-burst", "9 (0.44%, 1.33)", "product-rule", "weak", "generalisable", ["5900039933"])
c(13, "§0.2 July 2020 pop-up; §0.9 #2", "anti-pattern", "July 2020 — the pop-up that bought for you: PAY_NAG 44 (2.17%, meaningful, mean 2.02), first 5 Jul 2020, still reported Dec 2024; PAY_FORCED 20 (0.99%, emerging, mean 1.25), all 10 Jul 2020 → 3 Jan 2021; in July 2020 alone 35 of 68 reviews (51.5%) carry one or both — 'I clicked on the x at the top, but instead of giving me the data screen, it acted like I'd tried to make a purchase' (us, 4★); 'The pop up has a fake X in the top corner to close the message, which if you press, causes your account to agree to the premium subscription' (gb, 1★); decision: remove the every-launch upsell and any close control that can start a purchase (E4 mean 2.72)", "every-launch full-screen upsell; close control starts purchase", "1★-burst", "PAY_NAG 44 (2.02); PAY_FORCED 20 (1.25); Jul 2020 35 of 68 (51.5%)", "dont", "meaningful", "generalisable", ["6194515737","6217825775"])
c(14, "§0.3 table (verbatim)", "timeline", "Four crash waves, each tied to an update: BUG_CRASH 197 (9.73%, high-priority, mean 2.04); reliability union 434 (21.44%, 2.19) — Jul 2017 update crashes on launch (12 of 47, all 12 UK storefront); Jan 2018 registration hangs, 'buy premium' crashes (9 + 14 ACCT_BUG + 10 PAY_IAP_FAIL, us 33 of 62); Nov 2018 iOS 12 app closes on open (24 of 45, 23 in Brazil); Oct 2020 – Feb 2021 launch crash after the 2020 updates (30 of 70, 26 UK); BUG_UPDATE 43 (2.12%, 1.91); fixes reported twice, the second after 'nearly nine months of complaints' — each wave concentrated in one storefront", "update-triggered crash waves", "1★-burst", table("## 0.3 Four crash waves", 0), "must-never-break", "high-priority", "generalisable", ["1673186816","2061252128","3385514055","6706410264","1707578570","7097957463"])
c(15, "§0.4", "timeline", "Support silence and visible neglect: SUP_BAD 83 (4.10%, very strong, mean 1.45; 66 at 1★); neglect union 156 (7.71%, high-priority, 1.95) — DEV_ABANDON 42 (2.08%), BUG_COMPAT 53 (2.62%): no iPhone X layout from Nov 2017 until a Dec 2020 update; 'It's been out for over a year. Fix it' (2018); 'The last update was 9 months ago, this is unacceptable for a subscription based product' (us, 2★, Apr 2025)", "no new-screen support for three years; support silent", "churn", "SUP_BAD 83 (1.45); neglect 156 (1.95); iPhone X layout Nov 2017 → Dec 2020", "must-have", "very strong", "generalisable", ["1923610880","6718923959","3535806272","12574094084"])
c(16, "§0.5", "insight", "What works — a flexible tracker that changes behaviour: DES_CLEAN 475 (23.47%, high-priority, 4.89); CORE_FLEX 148 (7.31%, high-priority, 4.82) — 'You set your own standards (every day, certain days a week, or a number of days in a week/month)… it doesn't disqualify you if you don't do each habit every single day'; STAT_GOOD 187 (9.24%); CORE_STREAK 75 (3.71%); OUT_LIFE 151 (7.46%, 4.89) — 'a nail biter for 26 years but getting to tap yes! everyday is exactly what I needed to finally stop'; 'over 10K pushups… because I don't want to disappoint the app'; motivation union 362 (17.89%); design praise union 568 (28.06%); tracking-model union 346 (17.09%)", "flexible frequency, numeric habits, stats", "praise", "DES_CLEAN 475; CORE_FLEX 148 (4.82); STAT_GOOD 187; OUT_LIFE 151", "must-have", "high-priority", "generalisable", ["1327696946","5361919157","4608093672"])
c(17, "§0.6; §0.9 #4", "monetization", "The five-habit free tier is a differentiator and the upgrade trigger: PAY_FREE_OK 96 (4.74%, very strong, 4.86) — reviewers compare it favourably with three-habit tiers elsewhere; PAY_CAP 87 (4.30%, very strong, 3.98) — one of the two reasons payers most name for upgrading (with sync) and for others the reason not to; 'No annoying restrictions or constant pressure to upgrade. The makers take the free user seriously too' (nl, 5★, Jan 2018) — 'the product the July 2020 pop-up replaced'; decision: keep the five-habit free tier", "free: 5 habits", "praise", "PAY_FREE_OK 96 (4.86) vs PAY_CAP 87 (3.98)", "build-free", "very strong", "generalisable", ["3363102377","3728440907","1308688562","1335999992","1339211456","2193551017","14276683948","2090700914"])
c(18, "§0.7", "feature", "The app never reached the rest of the Apple ecosystem — device reach gaps 113 (5.58%, high-priority, mean 3.15): no iPad layout (IPAD 30, 1.48%), no Apple Watch, Mac or web app (PLATFORM_WANT 24, 1.19%), no widget (WIDGET_WANT 16, 0.79%), and the late new-screen layout; some reviewers left for this reason", "iPhone app stretched on iPad; no Watch, Mac, web, widget", "churn", "113 (5.58%, 3.15)", "must-have", "high-priority", "generalisable", ["2013414846","3257491999"])
c(19, "§0.8", "dont", "Small brand irritants that cost ratings — 30 (1.48%, meaningful, mean 3.03): the launch-screen photo of a woman hiker (DES_SPLASH 20, 0.99%, 2016–2022), the app icon (DES_ICON 6), pet-name messages (MOT_MSG_NEG 4) — 'I purchased premium. I am uninstalling due to lack of dev response to the main photo of the girl' (us, 1★, 2017); 'Deleted when the reminder called me cutie' (us, 2★, 2020)", "gendered splash photo; pet-name reminder copy", "churn", "30 (1.48%, 3.03); DES_SPLASH 20", "dont", "meaningful", "generalisable", ["1604334907","5378082186"])
c(20, "§0.9 table (verbatim)", "insight", "The five decisions (verbatim): 1 make what people paid for work — sync, restore and login — before any new paid feature (payer data & account failure 69 of 165; union 143, 7.07%); 2 remove the every-launch upsell and any close control that can start a purchase (PAY_NAG 44, PAY_FORCED 20; E4 2.72); 3 offer a one-time or lifetime option and honour earlier one-time buyers (PAY_REGRESS 9 at 1.33; PAY_SUB_NEG 19; PAY_PRICE_HIGH 42); 4 keep the five-habit free tier — praised more often than resented (PAY_FREE_OK 96 vs PAY_CAP); 5 a release process that stops launch crashes and a support channel that answers (BUG_CRASH 197; SUP_BAD 83; four dated waves)", "n/a", "n/a", table("## 0.9 The five decisions", 0), "product-rule", "table", "generalisable", [])

